 private final Runnable cursorTick=new Runnable(){public void run(){if(!running)return;if(Math.abs(stickX)>.18f||Math.abs(stickY)>.18f){px=Math.max(1,Math.min(game.getWidth()-2,px+stickX*17));py=Math.max(1,Math.min(game.getHeight()-2,py+stickY*17));showPointer();}handler.postDelayed(this,16);}};
 private void showPointer(){if(pointer==null)return;pointer.setVisibility(View.VISIBLE);pointer.setX(px-15);pointer.setY(py-15);}
 private boolean shortcut(KeyEvent e){int mapped;switch(e.getKeyCode()){case KeyEvent.KEYCODE_BUTTON_X:mapped=KeyEvent.KEYCODE_I;break;case KeyEvent.KEYCODE_BUTTON_Y:mapped=KeyEvent.KEYCODE_M;break;case KeyEvent.KEYCODE_BUTTON_L1:mapped=KeyEvent.KEYCODE_C;break;case KeyEvent.KEYCODE_BUTTON_R1:mapped=KeyEvent.KEYCODE_S;break;case KeyEvent.KEYCODE_BUTTON_B:case KeyEvent.KEYCODE_BUTTON_START:mapped=KeyEvent.KEYCODE_ESCAPE;break;default:return false;}game.dispatchKeyEvent(new KeyEvent(e.getDownTime(),e.getEventTime(),e.getAction(),mapped,e.getRepeatCount()));return true;}
 private void cycleSpell(int direction){if(companion==null)return;JSONArray a=companion.latest.optJSONArray("spells");if(a==null||a.length()==0)return;selectedSpell=selectedSpell<0?(direction<0?a.length()-1:0):(selectedSpell+direction+a.length())%a.length();JSONObject spell=a.optJSONObject(selectedSpell);if(spell!=null){activate(spell.optString("id"));android.widget.Toast.makeText(this,spell.optString("name"),android.widget.Toast.LENGTH_SHORT).show();}}
 private void triggerSpell(int direction){long now=SystemClock.uptimeMillis();if(now-lastTriggerAt>=220){lastTriggerAt=now;cycleSpell(direction);}}
 @Override public boolean dispatchGenericMotionEvent(MotionEvent e){if((e.getSource()&InputDevice.SOURCE_JOYSTICK)==InputDevice.SOURCE_JOYSTICK&&e.getAction()==MotionEvent.ACTION_MOVE){stickX=e.getAxisValue(MotionEvent.AXIS_X);stickY=e.getAxisValue(MotionEvent.AXIS_Y);boolean left=Math.max(e.getAxisValue(MotionEvent.AXIS_LTRIGGER),e.getAxisValue(MotionEvent.AXIS_BRAKE))>.6f,right=Math.max(e.getAxisValue(MotionEvent.AXIS_RTRIGGER),e.getAxisValue(MotionEvent.AXIS_GAS))>.6f;if(left&&!leftTrigger)triggerSpell(-1);if(right&&!rightTrigger)triggerSpell(1);leftTrigger=left;rightTrigger=right;return true;}return super.dispatchGenericMotionEvent(e);}
 @Override public boolean dispatchKeyEvent(KeyEvent e){int code=e.getKeyCode();boolean controller=(e.getSource()&InputDevice.SOURCE_GAMEPAD)==InputDevice.SOURCE_GAMEPAD||(e.getSource()&InputDevice.SOURCE_JOYSTICK)==InputDevice.SOURCE_JOYSTICK||(e.getSource()&InputDevice.SOURCE_DPAD)==InputDevice.SOURCE_DPAD;if(controller){if(code==KeyEvent.KEYCODE_BUTTON_SELECT){if(e.getAction()==KeyEvent.ACTION_DOWN&&e.getRepeatCount()==0&&companion!=null&&companion.latest.optBoolean("combat"))activate("end");return true;}if(shortcut(e))return true;if(code==KeyEvent.KEYCODE_BUTTON_L2||code==KeyEvent.KEYCODE_BUTTON_R2){if(e.getAction()==KeyEvent.ACTION_DOWN&&e.getRepeatCount()==0)triggerSpell(code==KeyEvent.KEYCODE_BUTTON_R2?1:-1);return true;}if(code==KeyEvent.KEYCODE_BUTTON_A){showPointer();long now=SystemClock.uptimeMillis();if(e.getAction()==KeyEvent.ACTION_DOWN&&e.getRepeatCount()==0){downAt=now;game.dispatchTouchEvent(MotionEvent.obtain(downAt,now,MotionEvent.ACTION_DOWN,px,py,0));}else if(e.getAction()==KeyEvent.ACTION_UP&&downAt!=0){game.dispatchTouchEvent(MotionEvent.obtain(downAt,now,MotionEvent.ACTION_UP,px,py,0));downAt=0;}return true;}if(e.getAction()==KeyEvent.ACTION_DOWN){switch(code){case KeyEvent.KEYCODE_DPAD_LEFT:px-=28;break;case KeyEvent.KEYCODE_DPAD_RIGHT:px+=28;break;case KeyEvent.KEYCODE_DPAD_UP:py-=28;break;case KeyEvent.KEYCODE_DPAD_DOWN:py+=28;break;default:return super.dispatchKeyEvent(e);}px=Math.max(1,Math.min(game.getWidth()-2,px));py=Math.max(1,Math.min(game.getHeight()-2,py));showPointer();return true;}}return super.dispatchKeyEvent(e);}
