 private void activate(String id){if(game==null||game.getUrl()==null||!game.getUrl().startsWith(HOME))return;String js;if(id.equals("end"))js="[...document.querySelectorAll('button')].find(x=>x.getClientRects().length && /^(Fin du tour|Prêt)$/i.test((x.innerText||'').trim()))?.click()";else if(id.matches("spell-slot-[0-9]+")||id.matches("bag-[0-9]+")||id.matches("menu-(inventory|quests|spells|stats)"))js="document.querySelector('[data-testid="+id+"]')?.click()";else return;game.evaluateJavascript(js,null);}
